// Garde-fou : WF0 ne doit tourner qu'une seule fois.
// On ne regarde que les incidents créés par la démo (correlation_id = demo-itsm) :
// les incidents d'exemple livrés avec l'instance sont ignorés.
const trouves = $input.all().filter(({ json }) => json.number || json.sys_id);
if (trouves.length > 0) {
  const ex = trouves[0].json.number || trouves[0].json.sys_id;
  throw new Error(`Des incidents de la démo existent déjà (par exemple ${ex}) : WF0 s'arrête pour ne pas créer de doublons. Supprimez-les dans ServiceNow (filtre : ID de corrélation = demo-itsm) avant de relancer.`);
}
return [{ json: { ok: true } }];

// Ne crée que les CI absents de la CMDB (relançable sans doublon de CI).
// Si tous existent déjà, renvoie un seul élément « rien à créer » pour que le flux continue.
const existants = new Set($('Chercher les CI existants').all().map(({ json }) => json.name).filter(Boolean));
const manquants = $('Liste des CI').all().map(({ json }) => json.name).filter((n) => !existants.has(n));
if (manquants.length === 0) return [{ json: { aCreer: false } }];
return manquants.map((name) => ({ json: { aCreer: true, name } }));

// Jeu de données de démo : 3 familles d'incidents récurrents + 4 incidents de bruit.
// Les CI viennent de la CMDB : ceux qui existaient déjà (« Chercher les CI existants »)
// et ceux que « Créer le CI » vient de créer. On les retrouve par leur nom.
const sysIds = {};
for (const { json } of $('Chercher les CI existants').all()) {
  if (json.name && json.sys_id) sysIds[json.name] = json.sys_id;
}
for (const { json } of $input.all()) {
  if (json.name && json.sys_id) sysIds[json.name] = json.sys_id;
}
const trouver = (nom) => {
  if (!sysIds[nom]) throw new Error(`CI introuvable dans la CMDB : ${nom}`);
  return sysIds[nom];
};
const CI = {
  erp: trouver('ERP-PROD'),
  partage: trouver('NAS-FICHIERS'),
  mail: trouver('MAIL-EXCH-01'),
};

const familles = [
  { ci: CI.erp, cat: 'software', textes: ['Lenteurs ERP en fin de mois',
    'ERP très lent sur la saisie des commandes', 'Temps de réponse ERP dégradé'] },
  { ci: CI.partage, cat: 'hardware', textes: ['Partage réseau inaccessible',
    'Accès refusé au partage réseau', 'Partage réseau déconnecté'] },
  { ci: CI.mail, cat: 'network', textes: ["Mails bloqués en file d'attente",
    'Mails non distribués', 'Retards de distribution des mails'] },
];
const bruit = ['Imprimante en panne au 2e étage', 'Mot de passe expiré',
  'Écran noir au démarrage', 'Licence Office à renouveler'];

const out = [];
for (const f of familles) {
  for (let i = 0; i < 6; i++) {
    out.push({ json: { short_description: f.textes[i % 3], category: f.cat, cmdb_ci: f.ci } });
  }
}
for (const t of bruit) out.push({ json: { short_description: t, category: 'inquiry', cmdb_ci: '' } });
return out;
